(function ($) {
  app.modals.ChangePasswordModal = function () {
    var _profileService = abp.services.app.profile;
    var _passwordComplexityHelper = new app.PasswordComplexityHelper();

    var _modalManager;
    var _$form = null;

    this.init = function (modalManager) {
      _modalManager = modalManager;

      _profileService.getPasswordComplexitySetting().done(function (result) {
        _$form = _modalManager.getModal().find('form[name=ChangePasswordModalForm]');
        _$form.validate({
          validClass: "valid",  // default
          errorClass: "invalid-feedback", // default is "error"
          highlight: function (element, errorClass, validClass) {
            $(element).addClass('is-invalid').removeClass('is-valid');
          },
          unhighlight: function (element, errorClass, validClass) {
            $(element).addClass('is-valid').removeClass('is-invalid');
          },
          rules: {
            NewPasswordRepeat: {
              required: true,
              equalTo: "#NewPassword"
            },
            NewPassword: {
              required: true,
              notEqualToCurrent: "#CurrentPassword"
            },
          },
          messages: {
            NewPasswordRepeat: {
              required: "Xác nhận mật khẩu không được bỏ trống",
              equalTo: "Xác nhận mật khẩu phải trùng với mật khẩu mới"
            },
            NewPassword: {
              required: "Mật khẩu mới không được bỏ trống",
              notEqualToCurrent: "Mật khẩu mới không được trùng với mật khẩu hiện tại"
            },
            CurrentPassword: {
              required: "Mật khẩu hiện tại không được bỏ trống",
            }
          },
          errorPlacement: function (error, element) {
            // Kiểm tra nếu element nằm trong Input Group
            if (element.closest('.input-group').length) {
              error.addClass('text-danger'); // Thêm class Bootstrap cho lỗi màu đỏ
              error.insertAfter(element.closest('.input-group')); // Đặt lỗi sau nhóm input
            } else if (element.closest('.form-check').length) { // Nếu là radio hoặc checkbox
              error.addClass('text-danger');
              error.appendTo(element.closest('.form-check')); // Đặt lỗi sau nhóm radio/checkbox
            } else {
              error.insertAfter(element); // Mặc định cho các trường input khác
            }
          },
          success: function (label, element) {
            $(element).next('.invalid-feedback').remove(); // Xóa thông báo lỗi khi input hợp lệ
          },
          success: function (label, element) {
            $(element).next('.invalid-feedback').remove(); // Remove error message on success
          }
        });

        _passwordComplexityHelper.setPasswordComplexityRules(
          _$form.find('input[name=NewPassword],input[name=NewPasswordRepeat]'),
          result.setting
        );
      });
    };

    this.save = function () {
      if (!_$form.valid()) {
        return;
      }

      _modalManager.setBusy(true);
      _profileService
        .changePassword(_$form.serializeFormToObject())
        .done(function () {
          abp.notify.info(app.localize('YourPasswordHasChangedSuccessfully'));
          _modalManager.close();
          // call csdlDulichProfileAppSerive.SetRecentPasswrod
        })
        .always(function () {
          _modalManager.setBusy(false);
        });
    };
  };
})(jQuery);
